#!/usr/bin/env python3
"""
Script to reproduce the progress value limitation issue.
This script demonstrates that currently only values between 0 and 1 are accepted,
but we want to support other ranges (like 0-100 or arbitrary ranges).
"""

import sys
import os
sys.path.insert(0, os.path.abspath('.'))

from sepal_ui import sepalwidgets as sw

def test_current_behavior():
    """Test the current behavior that restricts progress to [0, 1]"""
    print("Testing current behavior...")

    alert = sw.Alert()

    # Test valid range [0, 1] - should work
    try:
        alert.update_progress(0.0)
        print("✓ Progress 0.0 works")
    except Exception as e:
        print(f"✗ Progress 0.0 failed: {e}")

    try:
        alert.update_progress(0.5)
        print("✓ Progress 0.5 works")
    except Exception as e:
        print(f"✗ Progress 0.5 failed: {e}")

    try:
        alert.update_progress(1.0)
        print("✓ Progress 1.0 works")
    except Exception as e:
        print(f"✗ Progress 1.0 failed: {e}")

    # Test invalid range - should fail with ValueError
    try:
        alert.update_progress(1.5)
        print("✗ Progress 1.5 should have failed but didn't!")
    except ValueError as e:
        print(f"✓ Progress 1.5 correctly failed with: {e}")
    except Exception as e:
        print(f"? Progress 1.5 failed with unexpected error: {e}")

    try:
        alert.update_progress(-0.5)
        print("✗ Progress -0.5 should have failed but didn't!")
    except ValueError as e:
        print(f"✓ Progress -0.5 correctly failed with: {e}")
    except Exception as e:
        print(f"? Progress -0.5 failed with unexpected error: {e}")

def test_desired_behavior():
    """Test what we want to achieve - support for other ranges"""
    print("\nTesting desired behavior (will fail with current implementation)...")

    alert = sw.Alert()

    # We want to support values like 0-100 range
    try:
        # This should work with proper tqdm_args configuration
        alert.update_progress(50, total=100)
        print("✓ Progress 50 with total=100 should work")
    except Exception as e:
        print(f"✗ Progress 50 with total=100 failed: {e}")

    # We want to support arbitrary ranges
    try:
        # This should work with proper tqdm_args configuration
        alert.update_progress(25, total=50)
        print("✓ Progress 25 with total=50 should work")
    except Exception as e:
        print(f"✗ Progress 25 with total=50 failed: {e}")

    # We want to support absolute values when total is specified
    try:
        alert.update_progress(75, total=100)
        print("✓ Progress 75 with total=100 should work")
    except Exception as e:
        print(f"✗ Progress 75 with total=100 failed: {e}")

if __name__ == "__main__":
    test_current_behavior()
    test_desired_behavior()
